import org.junit.jupiter.api.Test;

class PackedTupleFunctionApiInputAssuranceTest {
	private static final Value FIXED = SimpleValueFactory.getInstance().createLiteral("request", "EN");

	@Test
	void actualApiFoldRetainsItsFlagValueAndAcceptedRowAssuranceWithoutRuntimeInput() {
		TupleFunctionCall call = call(Var.of("value"));
		MapBindingSet request = new MapBindingSet(); request.addBinding("value", FIXED);
		new BindingAssignerOptimizer().optimize(new QueryRoot(call), null, request);
		Var folded = call.getResultVars().getFirst();
		assertTrue(folded.hasApiInputOrigin()); assertTrue(folded.hasValue()); assertFalse(folded.isConstant());
		assertSame(FIXED, folded.getValue());
		assertEquals(Set.of("value"), call.getAssuredBindingNames());
		assertEquals(Set.of("value"), QueryAlgebraBindingAnalysis.withBindingValues(call, EmptyBindingSet.getInstance())
				.outputFacts(call).guaranteedOutputs());
		PackedQuery query = PackedQueryCodec.encodeForPlanning(call.clone());
		assertEquals(Set.of("value"), Set.copyOf(query.bindingNames(query.relAssuredMaskId(query.rootRelId()))));
		PackedQueryView view = new PackedQueryView(query);
		assertEquals(Set.of("value"), Set.copyOf(view.outputBindingNames(query.rootRelId())));
		TupleFunctionCall restored = assertInstanceOf(TupleFunctionCall.class, view.materializeRelation(query.rootRelId()));
		Var actual = restored.getResultVars().getFirst();
		assertTrue(actual.hasApiInputOrigin()); assertFalse(actual.isConstant()); assertEquals(FIXED, actual.getValue());
	}

	@Test
	void unvaluedAndAuthoredValuedPositionsKeepDistinctAssuranceAfterRoundTrip() {
		TupleFunctionCall call = call(Var.of("nullable"));
		call.addResultVars(Var.of("authored", FIXED), Var.of("fixed", FIXED, false, true), Var.of("flagged", null, false, true));
		PackedQuery query = PackedQueryCodec.encodeForPlanning(call.clone()); PackedQueryView view = new PackedQueryView(query);
		assertEquals(Set.of("nullable", "authored", "fixed", "flagged"), Set.copyOf(view.outputBindingNames(query.rootRelId())));
		assertEquals(Set.of("authored", "fixed"), Set.copyOf(query.bindingNames(query.relAssuredMaskId(query.rootRelId()))));
		TupleFunctionCall restored = assertInstanceOf(TupleFunctionCall.class, view.materializeRelation(query.rootRelId()));
		for (Var result : restored.getResultVars()) assertFalse(result.hasApiInputOrigin());
	}

	private static TupleFunctionCall call(Var result) {
		TupleFunctionCall call = new TupleFunctionCall(); call.setURI("urn:tuple-api-input:assurance"); call.addResultVar(result); return call;
	}
}
